import React, { useState } from 'react';
import { dashboardApi } from '../api/client';
import {
  PlayCircle,
  PauseCircle,
  Wrench,
  AlertTriangle,
  Gauge,
  Award,
  Zap,
  TrendingUp,
  X,
  CheckCircle2,
  Clock,
  UserCheck,
  Search,
  ExternalLink,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const SystemStatusBar = () => {
  const navigate = useNavigate();
  const [activeModal, setActiveModal] = useState(null);
  const [modalData, setModalData] = useState(null);
  const [loading, setLoading] = useState(false);

  const kpis = [
    {
      key: 'running',
      title: 'Running Machines',
      value: '16 / 20',
      status: '90% Operational',
      icon: PlayCircle,
      color: '#16A34A',
      bg: '#DCFCE7',
      borderColor: '#BBF7D0',
      route: '/assets',
    },
    {
      key: 'idle',
      title: 'Idle Machines',
      value: '2',
      status: 'Standby',
      icon: PauseCircle,
      color: '#D97706',
      bg: '#FEF3C7',
      borderColor: '#FDE68A',
      route: '/assets',
    },
    {
      key: 'maintenance',
      title: 'Scheduled Maintenance',
      value: '2',
      status: 'Scheduled Service',
      icon: Wrench,
      color: '#EA580C',
      bg: '#FFEDD5',
      borderColor: '#FED7AA',
      route: '/maintenance',
    },
    {
      key: 'alerts',
      title: 'Critical Alerts',
      value: '3',
      status: 'Immediate Action Required',
      icon: AlertTriangle,
      color: '#DC2626',
      bg: '#FEE2E2',
      borderColor: '#FECACA',
      route: '/alerts',
    },
    {
      key: 'production',
      title: "Today's Production",
      value: '14,250 m',
      status: 'Target 16,000 m (89%)',
      icon: Gauge,
      color: '#2563EB',
      bg: '#DBEAFE',
      borderColor: '#BFDBFE',
      route: '/analytics',
    },
    {
      key: 'oee',
      title: 'Overall Equipment Effectiveness (OEE)',
      value: '96.4%',
      status: 'World Class',
      icon: Award,
      color: '#7C3AED',
      bg: '#F3E8FF',
      borderColor: '#DDD6FE',
      route: '/ai-intelligence',
    },
    {
      key: 'energy',
      title: 'Energy Consumption',
      value: '1,245 kWh',
      status: 'Optimal Consumption',
      icon: Zap,
      color: '#059669',
      bg: '#ECFDF5',
      borderColor: '#A7F3D0',
      route: '/sensors',
    },
  ];

  const handleCardClick = async (kpi) => {
    try {
      setLoading(true);
      setActiveModal(kpi);
      const res = await dashboardApi.getKpiDetails(kpi.key);
      if (res && res.data && res.data.success) {
        setModalData(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch KPI details:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section style={{ width: '100%', marginBottom: '1.75rem' }}>
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
          gap: '1.5rem',
          width: '100%',
        }}
      >
        {kpis.map((kpi) => {
          const Icon = kpi.icon;
          return (
            <div
              key={kpi.key}
              onClick={() => handleCardClick(kpi)}
              style={{
                background: '#ffffff',
                borderRadius: '14px',
                padding: '1.5rem 1.75rem',
                border: `1px solid ${kpi.borderColor}`,
                boxShadow: '0 4px 18px rgba(0, 0, 0, 0.03)',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between',
                transition: 'all 0.25s ease',
                minHeight: '145px',
                cursor: 'pointer',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-3px)';
                e.currentTarget.style.boxShadow = '0 8px 25px rgba(0,0,0,0.08)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'none';
                e.currentTarget.style.boxShadow = '0 4px 18px rgba(0,0,0,0.03)';
              }}
            >
              {/* Header: Title & Icon */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '0.75rem' }}>
                <span style={{ fontSize: '0.92rem', fontWeight: '800', color: '#475569', lineHeight: '1.3' }}>
                  {kpi.title}
                </span>

                <div
                  style={{
                    width: '44px',
                    height: '44px',
                    borderRadius: '10px',
                    background: kpi.bg,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: kpi.color,
                    flexShrink: 0,
                  }}
                >
                  <Icon size={22} />
                </div>
              </div>

              {/* Body: Large Value & Status Line */}
              <div style={{ marginTop: '1.25rem' }}>
                <div
                  style={{
                    fontSize: '2.1rem',
                    fontWeight: '900',
                    color: '#0F172A',
                    lineHeight: '1.1',
                    letterSpacing: '-0.5px',
                    fontFamily: 'Plus Jakarta Sans, sans-serif',
                  }}
                >
                  {kpi.value}
                </div>

                <div
                  style={{
                    fontSize: '0.82rem',
                    fontWeight: '700',
                    color: kpi.color,
                    marginTop: '0.4rem',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                  }}
                >
                  <span style={{ display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
                    <TrendingUp size={13} /> {kpi.status}
                  </span>
                  <span style={{ fontSize: '0.74rem', color: '#2563EB', fontWeight: '800' }}>Inspect Details →</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* RICH KPI DEEP INSPECTION DRAWER MODAL */}
      {activeModal && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(15, 23, 42, 0.55)',
            backdropFilter: 'blur(4px)',
            zIndex: 1000,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '1.5rem',
          }}
        >
          <div
            className="glass-card"
            style={{
              background: '#ffffff',
              borderRadius: '16px',
              width: '100%',
              maxWidth: '680px',
              padding: '1.75rem',
              boxShadow: '0 20px 50px rgba(0,0,0,0.25)',
              border: `2px solid ${activeModal.color}`,
              maxHeight: '85vh',
              overflowY: 'auto',
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', paddingBottom: '0.75rem', borderBottom: '1px solid #E2E8F0' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.65rem' }}>
                <div style={{ width: '38px', height: '38px', borderRadius: '10px', background: activeModal.bg, color: activeModal.color, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {React.createElement(activeModal.icon, { size: 20 })}
                </div>
                <div>
                  <h3 style={{ fontSize: '1.1rem', fontWeight: '900', color: '#0F172A' }}>{activeModal.title}</h3>
                  <span style={{ fontSize: '0.78rem', color: '#64748B', fontWeight: '700' }}>Live Express Backend Telemetry Data</span>
                </div>
              </div>
              <button
                onClick={() => {
                  setActiveModal(null);
                  setModalData(null);
                }}
                style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#64748B' }}
              >
                <X size={20} />
              </button>
            </div>

            {loading ? (
              <div style={{ padding: '2rem', textAlign: 'center', color: '#2563EB', fontWeight: '800' }}>
                Loading Backend Data...
              </div>
            ) : modalData ? (
              <div>
                <div style={{ padding: '0.85rem 1rem', background: '#F8FAFC', borderRadius: '8px', border: '1px solid #E2E8F0', marginBottom: '1.25rem', fontSize: '0.85rem', color: '#0F172A', fontWeight: '700' }}>
                  {modalData.summary}
                </div>

                {/* Machines List (for Running / Idle) */}
                {modalData.machines && (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.65rem' }}>
                    <div style={{ fontSize: '0.82rem', fontWeight: '800', color: '#475569' }}>REGISTERED LOOM STATUS LIST:</div>
                    {modalData.machines.map((m) => (
                      <div key={m.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0.75rem 1rem', background: '#ffffff', border: '1px solid #E2E8F0', borderRadius: '8px' }}>
                        <div>
                          <strong style={{ color: '#2563EB', fontFamily: 'JetBrains Mono' }}>{m.id}</strong> — {m.name}
                          {m.reason && <div style={{ fontSize: '0.76rem', color: '#D97706', marginTop: '2px' }}>Reason: {m.reason}</div>}
                        </div>
                        <div style={{ textAlign: 'right', fontSize: '0.8rem', color: '#0F172A', fontWeight: '700' }}>
                          {m.rpm && <div>Speed: {m.rpm} RPM</div>}
                          {m.temp && <div style={{ color: '#EF4444' }}>Temp: {m.temp}</div>}
                          {m.operator && <div style={{ color: '#64748B', fontSize: '0.72rem' }}>Op: {m.operator}</div>}
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Work Orders List (for Maintenance) */}
                {modalData.workOrders && (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.65rem' }}>
                    <div style={{ fontSize: '0.82rem', fontWeight: '800', color: '#475569' }}>ACTIVE WORK ORDERS:</div>
                    {modalData.workOrders.map((wo) => (
                      <div key={wo._id} style={{ padding: '0.85rem 1rem', background: '#FFEDD5', border: '1px solid #FED7AA', borderRadius: '8px', fontSize: '0.82rem' }}>
                        <div style={{ fontWeight: '900', color: '#EA580C' }}>{wo.workOrder} — {wo.assetName} ({wo.machineId})</div>
                        <div style={{ color: '#0F172A', fontWeight: '700', marginTop: '3px' }}>{wo.type}</div>
                        <div style={{ fontSize: '0.75rem', color: '#64748B', marginTop: '4px' }}>Engineer: {wo.engineer} • Status: {wo.status}</div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Alerts List */}
                {modalData.alerts && (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.65rem' }}>
                    <div style={{ fontSize: '0.82rem', fontWeight: '800', color: '#475569' }}>ACTIVE ANOMALY ALERTS:</div>
                    {modalData.alerts.map((alt) => (
                      <div key={alt._id} style={{ padding: '0.85rem 1rem', background: '#FEE2E2', border: '1px solid #FECACA', borderRadius: '8px', fontSize: '0.82rem' }}>
                        <div style={{ fontWeight: '900', color: '#DC2626' }}>{alt.message}</div>
                        <div style={{ fontSize: '0.75rem', color: '#64748B', marginTop: '4px' }}>Loom: {alt.machineId} ({alt.machineName})</div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Shifts (for Production) */}
                {modalData.shifts && (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.65rem' }}>
                    <div style={{ fontSize: '0.82rem', fontWeight: '800', color: '#475569' }}>SHIFT YIELD BREAKDOWN:</div>
                    {modalData.shifts.map((s, idx) => (
                      <div key={idx} style={{ display: 'flex', justifyContent: 'space-between', padding: '0.75rem 1rem', background: '#DBEAFE', border: '1px solid #BFDBFE', borderRadius: '8px', fontSize: '0.84rem' }}>
                        <div><strong>{s.shift}</strong> — {s.meters.toLocaleString()} m</div>
                        <div style={{ fontWeight: '800', color: '#2563EB' }}>{s.status}</div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Metrics (for OEE) */}
                {modalData.metrics && (
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.75rem' }}>
                    <div style={{ padding: '0.75rem', background: '#F3E8FF', borderRadius: '8px', textAlign: 'center' }}>
                      <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>AVAILABILITY</div>
                      <div style={{ fontSize: '1rem', fontWeight: '900', color: '#7C3AED' }}>{modalData.metrics.availability}</div>
                    </div>
                    <div style={{ padding: '0.75rem', background: '#F3E8FF', borderRadius: '8px', textAlign: 'center' }}>
                      <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>PERFORMANCE</div>
                      <div style={{ fontSize: '1rem', fontWeight: '900', color: '#7C3AED' }}>{modalData.metrics.performance}</div>
                    </div>
                    <div style={{ padding: '0.75rem', background: '#F3E8FF', borderRadius: '8px', textAlign: 'center' }}>
                      <div style={{ fontSize: '0.7rem', color: '#64748B', fontWeight: '800' }}>QUALITY</div>
                      <div style={{ fontSize: '1rem', fontWeight: '900', color: '#7C3AED' }}>{modalData.metrics.quality}</div>
                    </div>
                  </div>
                )}

                {/* Energy Load Stats */}
                {modalData.powerFactor && (
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '0.75rem', fontSize: '0.85rem' }}>
                    <div style={{ padding: '0.75rem', background: '#ECFDF5', borderRadius: '8px' }}>
                      Power Factor: <strong style={{ color: '#059669' }}>{modalData.powerFactor}</strong>
                    </div>
                    <div style={{ padding: '0.75rem', background: '#ECFDF5', borderRadius: '8px' }}>
                      Peak Demand: <strong style={{ color: '#059669' }}>{modalData.peakDemandKw}</strong>
                    </div>
                    <div style={{ padding: '0.75rem', background: '#ECFDF5', borderRadius: '8px' }}>
                      CO₂ Saved: <strong style={{ color: '#059669' }}>{modalData.co2SavedKg}</strong>
                    </div>
                    <div style={{ padding: '0.75rem', background: '#ECFDF5', borderRadius: '8px' }}>
                      Daily Cost Est: <strong style={{ color: '#059669' }}>{modalData.dailyCostEstINR}</strong>
                    </div>
                  </div>
                )}

                <div style={{ marginTop: '1.25rem', display: 'flex', justifyContent: 'flex-end', gap: '0.75rem' }}>
                  <button
                    className="btn btn-primary btn-sm"
                    onClick={() => {
                      setActiveModal(null);
                      navigate(activeModal.route);
                    }}
                    style={{ background: activeModal.color, borderColor: activeModal.color, fontWeight: '800' }}
                  >
                    Open {activeModal.title} Module <ExternalLink size={14} />
                  </button>
                </div>
              </div>
            ) : null}
          </div>
        </div>
      )}
    </section>
  );
};

export default SystemStatusBar;
